import React, { Component } from 'react'
import {
  Row, Button, Icon, Table, Spin, Col, Card, Alert, Modal, message,
  notification, Select, Input, InputNumber, DatePicker
} from 'antd'
import { connect } from 'react-redux'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import LayoutContent from '../../../../components/utility/layoutContent'
import GocarStyled from './gocar.style'
import gocarAction from '../../../redux/gocar/actions'
import notificationsActions from '../../../redux/notifications/actions'
import moment from 'moment'
import JSZip from 'jszip'
import JSZipUtils from 'jszip-utils'
import { saveAs } from 'file-saver/FileSaver'
import { carInformationColumns, columnsNotifications, columnsPayment } from '../GocarComponents/tableData'
import { driverTerminateReason } from '../GocarComponents/optionData'
import { driverRejectWarningMessage } from '../GocarComponents/messageData'
import loadingActions from '../../../../redux/loading/actions'
import errorActions from '../../../../redux/error/actions'

const { Option } = Select
const { TextArea } = Input
const { MonthPicker } = DatePicker
const { Meta } = Card
const { updatePolicyNumber, getGocarDetails, getGocarPaymentDetails, cancelPolicy,
  resetReduxState, terminatePolicy, checkMissingPayment, addPayment
} = gocarAction
const { resetNotificationsRedux, getNotificationList, postRetriggerNotification } = notificationsActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class GocarDetail extends Component {
  constructor (props) {
    super(props)
    this.state = {
      policyNumberEditable: true,
      policyNumber: '',
      detailsData: {},
      payment: [],
      error: false,
      internalId: '',
      statusCancelPolicy: '',
      statusTerminatePolicy: '',
      cancellationLoader: false,
      terminationLoader: false,
      notificationsData: {},
      modalEmailContent: '',
      emailContentPopUp: false,
      loadingNotificationsList: true,
      showMissingPaymentModal: false,
      terminateReason: '',
      terminateMessage: '',
      showTerminationModel: false,
      showMissingPaymentModel: false,
      showAddPaymentModal: false,
      paymentAmount: undefined,
      paymentDate: '',
      transactionRefernce: undefined
    }
  }

  componentWillReceiveProps (nextProps) {
    const { data, status, payment, statusCancelPolicy, statusTerminatePolicy } = nextProps.gocarData
    const { data: notificationsData, getNotficationsListStatus, retriggerNotificationStatus } = nextProps.notifications
    const { params } = this.props.location.state
    if (getNotficationsListStatus !== '') {
      this.setState({
        notificationsData,
        getNotficationsListStatus,
        loadingNotificationsList: false
      })
    }
    if (statusCancelPolicy !== undefined) {
      this.setState({ statusCancelPolicy, cancellationLoader: false })
    }
    if (statusTerminatePolicy !== undefined) {
      this.setState({ statusTerminatePolicy, terminationLoader: false })
    }
    if (status !== 'success' && status !== '') {
      this.setState({ error: true })
    }
    if (data && status === 'success') {
      this.setState({
        detailsData: data,
        policyNumber: data.InsurancePolicyNo
      })
    }
    if (payment !== undefined) {
      this.setState({ payment })
    }
    if (retriggerNotificationStatus !== '') {
      message.info(retriggerNotificationStatus)
      this.props.resetNotificationsRedux(['retriggerNotificationStatus'])
    }

    if (nextProps.terminatePolicyLoading === false) {
      notification[nextProps.terminatePolicyError ? 'error' : 'success']({
        message: nextProps.cancelPolicyStatus
      })
      if (nextProps.terminatePolicyError === false) {
        this.props.history.push({ pathname: `/gocar/suspend/komplit/${params.internalID}`, state: { params: { internalID: params.internalID } } })
        this.setState({ showCancellationModel: false })
      }
      this.props.resetLoadingRedux(['TERMINATE_POLICY'])
      this.props.resetErrorRedux(['TERMINATE_POLICY'])
    }

    if (nextProps.addPaymentLoading === false) {
      notification[nextProps.addPaymentError ? 'error' : 'success']({
        message: nextProps.addPaymentStatus
      })
      if (nextProps.addPaymentError === false) {
        this.props.getGocarPaymentDetails({ partner_code: 'gocar', policy_id: params.internalID })
        this.setState({ showAddPaymentModal: false, paymentAmount: undefined, transactionRefernce: undefined })
      }
      this.props.resetLoadingRedux(['ADD_PAYMENT'])
      this.props.resetErrorRedux(['ADD_PAYMENT'])
    }
  }

  componentDidMount () {
    if (this.props.location.state !== undefined) {
      const { params } = this.props.location.state
      this.setState({ internalId: params.internalID })
      this.props.getGocarDetails(params.internalID)
      this.props.getGocarPaymentDetails({ partner_code: 'gocar', policy_id: params.internalID })
      this.props.resetNotificationsRedux()
      this.props.getNotificationList({ query: { reference_id: params.internalID } })
    }
  }

  componentWillUnmount () {
    this.resetState()
  }

  resetState = () => {
    this.props.resetReduxState()
  }

  onBackGocarData = () => {
    const { history } = this.props
    this.resetState()
    history.push('/gocar/komplit')
  }

  insuranceEditable = () => {
    this.setState({ policyNumberEditable: !this.state.policyNumberEditable })
  }

  gojekIdEditable = () => {
    this.setState({ gojekIdEditable: !this.state.gojekIdEditable })
  }

  changePolicyNumberInput = val => {
    this.setState({ policyNumber: val.target.value })
  }

  changeGojekId = val => {
    this.setState({ gojekId: val.target.value })
  }

  updatePolicyNumber = () => {
    const { params } = this.props.location.state
    if (this.state.policyNumber !== '') {
      this.setState({ policyNumberEditable: true })
      this.props.updatePolicyNumber({
        id: params.internalID,
        policy_no: this.state.policyNumber,
        identifier: 'komplit'
      })
    }
  }

  onUpdateGojekId = () => {
    const { data } = this.props.location.state.params
    if (this.state.gojekId !== '') {
      this.setState({ gojekIdEditable: true })
      this.props.updateGojekId({
        id: data.InternalID,
        policy_no: '',
        driver_id: this.state.gojekId
      })
    }
  }

  handlePreview = file => {
    this.setState({
      previewImage: file,
      previewVisible: true
    })
  }

  fetchImages = (images, vehicleImages) => {
    let finalImages = []
    vehicleImages.forEach((values, index) => {
      finalImages = [...finalImages, values]
    })
    images.forEach((values, index) => {
      finalImages = [...finalImages, values]
    })
    return finalImages.map((values, index) => {
      return (
        <Col span={6} key={index}>
          <div key={index} style={{ margin: '20px' }}>
            <Card
              hoverable
              style={{ width: 240 }}
              cover={<img alt={values.file_name} src={values.url} onClick={() => this.handlePreview(values.url)} />}
            >
              <Meta description={values.file_name} />
            </Card>
          </div>
        </Col>
      )
    })
  }

  handleCancelImagePopup = () => this.setState({ previewVisible: false })

  downloadAllPhotos (images) {
    this.setState({ imageDownloadLoader: true })
    let urls = images
    let nombre = 'gocar_komplit_images_' + moment().format('YYYY-MM-DD')
    compressedImg(urls, nombre)
    const _this = this
    function compressedImg (urls, nombre) {
      let zip = new JSZip()
      let count = 0
      let name = nombre + '.zip'
      urls.forEach(url => {
        JSZipUtils.getBinaryContent(url, (err, data) => {
          if (err) {
            throw err
          }
          const getName = url.split('/')[4]
          zip.file(getName, data, { binary: true })
          count++
          if (count === urls.length) {
            zip.generateAsync({ type: 'blob' }).then(content => {
              saveAs(content, name)
            })
            _this.setState({ imageDownloadLoader: false })
          }
        })
      })
    }
  }

  driverCancellation = internalId => {
    this.setState({ cancellationLoader: true })
    this.props.cancelPolicy(internalId)
  }

  driverTermination = internalId => {
    this.setState({ terminationLoader: true })
    this.props.terminatePolicy(internalId)
  }

  retriggerNotification = (deliveryID, recipient) => {
    this.props.resetNotificationsRedux(['retriggerNotificationStatus'])
    this.props.postRetriggerNotification({ body: { delivery_id: deliveryID, recipient: recipient } })
  }

  showEmailModal = (modalEmailContent) => {
    this.setState({
      emailContentPopUp: true,
      modalEmailContent
    })
  }

  onCheckMissingPayment = () => {
    this.setState({ showMissingPaymentModal: true })
  }

  handleOk = (e) => {
    this.setState({
      emailContentPopUp: false
    })
  }

  handleCancel = (e) => {
    this.setState({
      emailContentPopUp: false
    })
  }

  handleDriverTerminate = () => {
    const { dataProfile } = this.props
    const { terminateReason, terminateMessage, internalId } = this.state
    if (terminateReason !== '' || (terminateReason === 'Others' && terminateMessage === '')) {
      const reason = terminateReason === 'Others' ? terminateMessage : terminateReason
      this.props.terminatePolicy({
        body: {
          internalId,
          reason,
          execution_date: moment().format('YYYY-MM-DD hh:mm:ss'),
          user: dataProfile.email
        }
      })
    } else {
      notification['error']({ message: 'Please add reason' })
    }
  }

  onCheckMissingPayment = () => {
    const { internalId } = this.state
    this.setState({ showMissingPaymentModel: true })
    this.props.checkMissingPayment({
      query: {
        id: internalId
      }
    })
  }

  handleAddPayment = () => {
    const { paymentAmount, paymentDate, detailsData = {}, transactionRefernce } = this.state
    const premium = Number(detailsData['Request.premium'])

    if (paymentAmount === 0 || paymentDate === '' || !transactionRefernce) {
      notification['error']({ message: 'Please input valid data' })
    } else if (!Number.isInteger(paymentAmount / premium)) {
      notification['error']({ message: 'Payment Amount is not valid' })
    } else {
      const date = moment(paymentDate).endOf('month').format('DD')
      const dateString = paymentDate + '-' + date
      this.props.addPayment({
        body: {
          amount: paymentAmount.toString(),
          txn_date: dateString,
          partner_key: 'gocar',
          product_key: 'go-car-complete',
          txn_ref: transactionRefernce,
          tag1: detailsData.Tag1
        }
      })
    }
  }

  handleAddPaymentShow = () => {
    this.setState({ showMissingPaymentModel: false, showAddPaymentModal: true })
  }

  render () {
    const {
      detailsData,
      payment,
      previewVisible,
      previewImage,
      notificationsData,
      modalEmailContent,
      emailContentPopUp,
      loadingNotificationsList,
      showTerminationModel,
      terminateReason,
      showMissingPaymentModel,
      showAddPaymentModal,
      paymentAmount,
      transactionRefernce
    } = this.state
    const { permissions, terminatePolicyLoading, missingPayments = {}, checkMissingPaymentLoading, addPaymentLoading } = this.props
    const { Amount = 0, NumberOfPayments = 0 } = missingPayments
    const filterPermissionDownloadImages = permissions.filter(val => val === 'ops.download_gocar_complete_images')
    const filterPermissionTermination = permissions.filter(val => val === 'ops.gocar_complete_terminate_policy')
    let loader = false
    if (Object.values(detailsData).length === 0) {
      loader = true
    }
    const columns = [{
      dataIndex: 'name',
      width: 150
    }, {
      dataIndex: 'value'
    }]
    const value1 = [{
      key: '1',
      name: <strong>Application No</strong>,
      value: detailsData.ApplicationNo || '-'
    }, {
      key: '2',
      name: <strong>Internal Id</strong>,
      value: detailsData.InternalID || '-'
    }, {
      key: '3',
      name: <strong>Product Key</strong>,
      value: detailsData.ProductDisplayName || '-'
    }, {
      key: '4',
      name: <strong>Full name</strong>,
      value: detailsData['Request.full_name'] || '-'
    }, {
      key: '5',
      name: <strong>Date of birth</strong>,
      value: detailsData['Request.dob'] || '-'
    }, {
      key: '6',
      name: <strong>Email</strong>,
      value: detailsData.Email || '-'
    }, {
      key: '7',
      name: <strong>Handphone</strong>,
      value: detailsData.MobileNo || '-'
    }, {
      key: '8',
      name: <strong>Engine number</strong>,
      value: detailsData['Request.engine_no'] || '-'
    }, {
      key: '9',
      name: <strong>Frame number</strong>,
      value: detailsData['Request.frame_no'] || '-'
    }, {
      key: '10',
      name: <strong>Sim number</strong>,
      value: detailsData['Request.license_no'] || '-'
    }, {
      key: '11',
      name: <strong>Nominee</strong>,
      value: detailsData['Request.nominee'] || '-'
    }, {
      key: 'relationship_with_nominee',
      name: <strong>Relationship with Nominee</strong>,
      value: detailsData['Request.relationship_with_nominee'] || '-'
    }, {
      key: '12',
      name: <strong>Package</strong>,
      value: detailsData['Request.package'] || '-'
    }]

    const dataPayment = payment.map((val, index) => {
      return {
        key: index,
        ID: val.ID,
        ApplicationNo: val.ApplicationNo,
        Amount: val.Amount,
        TxnRef: val.TxnRef,
        TxnDate: moment(val.TxnDate).format('DD MMMM YYYY'),
        CoverageStartDate: moment(val.CoverageStartDate).format('DD MMMM YYYY'),
        CoverageEndDate: moment(val.CoverageEndDate).format('DD MMMM YYYY')
      }
    })

    let finalImages = []
    if (detailsData['Request.personal_data_images'] && detailsData['Request.personal_data_images'].length !== 0) {
      detailsData['Request.personal_data_images'].forEach((values, index) => {
        finalImages = [...finalImages, values.url]
      })
      detailsData['Request.vehicle_images'].forEach((values, index) => {
        finalImages = [...finalImages, values.url]
      })
    }
    return (
      <LayoutContentWrapper>
        <Modal
          title='Content'
          visible={emailContentPopUp}
          onOk={this.handleOk}
          onCancel={this.handleCancel}
          width='100%'
          bodyStyle={{
            height: `${window.innerHeight * 0.75}px`
          }}
        >
          <iframe
            width='100%'
            height='100%'
            srcDoc={modalEmailContent}
            title='Email Content'
          />
        </Modal>
        <Modal
          title='Terminate Driver'
          visible={showTerminationModel}
          onCancel={() => this.setState({ showTerminationModel: false })}
          onOk={this.handleDriverTerminate}
        >
          <Spin spinning={!!terminatePolicyLoading}>
            <Row type='flex' justify='space-between' align='middle'>
              <Col>
                Alasan Terminate Driver
              </Col>
              <Col>
                <Select
                  placeholder='Please select a reason'
                  style={{ width: '260px' }}
                  onSelect={(val) => this.setState({ terminateReason: val })}
                  dropdownMatchSelectWidth={false}
                >
                  {
                    driverTerminateReason.map(reason =>
                      <Option key={reason} value={reason}>{reason}</Option>
                    )
                  }
                </Select>
              </Col>
            </Row>
            <Row>
              {
                terminateReason === 'Others' &&
                <TextArea
                  placeholder='Enter reason'
                  style={{ width: '260px', float: 'right', marginTop: 12 }}
                  onChange={(e) => this.setState({ terminateMessage: e.target.value })}
                />
              }
            </Row>
            <Row style={{ marginTop: '12px' }}>
              {driverRejectWarningMessage}
            </Row>
          </Spin>
        </Modal>
        <Modal
          title='Missing Payment'
          visible={showMissingPaymentModel}
          okText='Add Payment'
          onCancel={() => this.setState({ showMissingPaymentModel: false })}
          onOk={this.handleAddPaymentShow}
          okButtonProps={{ disabled: !!checkMissingPaymentLoading }}
        >
          <Spin spinning={!!checkMissingPaymentLoading}>
            <tr>
              <td>
                Number of missing payments
              </td>
              <td>
                : {NumberOfPayments}
              </td>
            </tr>
            <tr>
              <td>
                Total Pending Payment
              </td>
              <td>
                : {Amount}
              </td>
            </tr>
          </Spin>
        </Modal>
        <Modal
          title='Add payment'
          visible={showAddPaymentModal}
          onCancel={() => this.setState({ showAddPaymentModal: false, paymentAmount: undefined, transactionRefernce: undefined })}
          onOk={this.handleAddPayment}
        >
          <Spin spinning={!!addPaymentLoading}>
            <GocarStyled>
              <Row>
                <Col span={12}> Premium </Col>
                <Col span={12}> {detailsData['Request.premium']} </Col>
              </Row>
              <Row>
                <Col span={12}> Payment Amount </Col>
                <Col span={12}> <InputNumber onChange={e => this.setState({ paymentAmount: e })} value={paymentAmount} /> </Col>
              </Row>
              <Row>
                <Col span={12}> Payment Date </Col>
                <Col span={12}> <MonthPicker onChange={(e, monthYear) => this.setState({ paymentDate: monthYear })} /> </Col>
              </Row>
              <Row>
                <Col span={12}> Transaction Reference </Col>
                <Col span={12}> <Input onChange={(e) => this.setState({ transactionRefernce: e.target.value })} value={transactionRefernce} /> </Col>
              </Row>
              <Row>
                <Col span={12}>Number of Payments </Col>
                <Col span={12}>
                  {Number.isInteger(paymentAmount / detailsData['Request.premium'])
                    ? paymentAmount / detailsData['Request.premium']
                    : <div style={{ color: 'red' }}>Invalid Amount</div>
                  }
                </Col>
              </Row>
            </GocarStyled>
          </Spin>
        </Modal>
        {this.state.error && (
          <Row style={{ width: '100%' }}>
            <Col span={24}>
              <Alert style={{ marginBottom: '20px' }} message='Ooops, something went terribly wrong!' type='error' closeText='Close' />
            </Col>
          </Row>
        )}
        {(this.state.statusCancelPolicy !== 'success' && this.state.statusCancelPolicy !== '') && (
          <Row style={{ width: '100%' }}>
            <Col span={24}>
              <Alert
                style={{ marginBottom: '20px' }}
                message={this.state.statusCancelPolicy}
                type='error'
                closeText='Close'
                onClose={() => this.resetState()}
              />
            </Col>
          </Row>
        )}
        {(this.state.statusCancelPolicy === 'success' && this.state.statusCancelPolicy !== '') && (
          <Row style={{ width: '100%' }}>
            <Col span={24}>
              <Alert
                style={{ marginBottom: '20px' }}
                message='Policy has been cancelled successfully'
                type='success'
                closeText='Close'
                onClose={() => this.resetState()}
              />
            </Col>
          </Row>
        )}
        {(this.state.statusTerminatePolicy !== 'success' && this.state.statusTerminatePolicy !== '') && (
          <Row style={{ width: '100%' }}>
            <Col span={24}>
              <Alert
                style={{ marginBottom: '20px' }}
                message={this.state.statusTerminatePolicy}
                type='error'
                closeText='Close'
                onClose={() => this.resetState()}
              />
            </Col>
          </Row>
        )}
        {(this.state.statusTerminatePolicy === 'success' && this.state.statusTerminatePolicy !== '') && (
          <Row style={{ width: '100%' }}>
            <Col span={24}>
              <Alert
                style={{ marginBottom: '20px' }}
                message='Policy has been terminated successfully'
                type='success'
                closeText='Close'
                onClose={() => this.resetState()}
              />
            </Col>
          </Row>
        )}
        <LayoutContent>
          <GocarStyled>
            <Spin tip='Loading ...' spinning={loader}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px', marginRight: '10px' }}>
                <Button
                  type='primary'
                  onClick={this.onBackGocarData}
                  style={{ marginRight: '20px' }}
                >
                  <Icon type='left' />Back
                </Button>
                <div>
                  {
                    filterPermissionTermination.length > 0 && (
                      <Button
                        type='danger'
                        onClick={() => this.setState({ showTerminationModel: true })}
                      >
                        Terminate Policy
                      </Button>
                    )
                  }

                </div>
              </div>
              <div>
                <Row>
                  <Modal visible={previewVisible} footer={null} onCancel={this.handleCancelImagePopup}>
                    <img alt='gocar-images' style={{ width: '100%' }} src={previewImage} />
                  </Modal>
                  <Table pagination={{ pageSize: 25 }} showHeader={false} columns={columns} dataSource={value1} />
                </Row>
              </div>
            </Spin>
          </GocarStyled>
        </LayoutContent>
        <div style={{ marginTop: '30px', width: '100%' }}>
          <LayoutContent style={{ width: '100%', height: 'unset' }}>
            <GocarStyled>
              <Spin tip='Loading ...' spinning={loader}>
                <h3>Car Information</h3>
                <Row>
                  <Table
                    pagination={false}
                    columns={carInformationColumns()}
                    dataSource={[detailsData]}
                  />
                </Row>
              </Spin>
            </GocarStyled>
          </LayoutContent>
        </div>
        <div style={{ marginTop: '30px', width: '100%' }}>
          <LayoutContent style={{ width: '100%', height: 'unset' }}>
            <GocarStyled>
              <Spin tip='Loading ...' spinning={loader}>
                <Row type='flex' justify='space-between' align='middle' style={{ marginBottom: 4 }}>
                  <h3>Payment History</h3>
                  <Button
                    type='primary'
                    onClick={this.onCheckMissingPayment}
                  >
                    Check Missing Payment
                  </Button>
                </Row>
                <Row>
                  <Col span={24}>
                    <Table
                      pagination={{ pageSize: 25 }}
                      columns={columnsPayment()}
                      dataSource={dataPayment}
                    />
                  </Col>
                </Row>
              </Spin>
            </GocarStyled>
          </LayoutContent>
        </div>
        <div style={{ marginTop: '30px', width: '100%' }}>
          <LayoutContent style={{ width: '100%', height: 'unset' }}>
            <GocarStyled>
              <Spin tip='Loading ...' spinning={loader}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <h3>Photos</h3>
                  {
                    filterPermissionDownloadImages.length > 0 && (
                      <Button
                        type='primary'
                        icon='cloud'
                        loading={this.state.imageDownloadLoader}
                        onClick={() => this.downloadAllPhotos(finalImages)}
                        style={{ marginRight: '20px' }}
                      >
                        Download All photos
                      </Button>
                    )
                  }
                </div>
                <div style={{ display: 'flex' }}>
                  <Row>
                    {
                      detailsData['Request.personal_data_images'] && detailsData['Request.personal_data_images'].length !== 0 ? (
                        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
                          {this.fetchImages(detailsData['Request.personal_data_images'], detailsData['Request.vehicle_images'])}
                        </div>
                      ) : <h5>No images found!</h5>
                    }
                  </Row>
                </div>
              </Spin>
            </GocarStyled>
          </LayoutContent>
        </div>
        <div style={{ marginTop: '30px', width: '100%' }}>
          <LayoutContent style={{ width: '100%', height: 'unset' }}>
            <GocarStyled>
              <Spin tip='Loading ...' spinning={loadingNotificationsList}>
                <h3>Notifications List</h3>
                <Row>
                  <Col span={24}>
                    <Table
                      scroll={{ x: true }}
                      pagination={{ pageSize: 10 }}
                      showHeader
                      columns={columnsNotifications(this)}
                      dataSource={notificationsData.data} />
                  </Col>
                </Row>
              </Spin>
            </GocarStyled>
          </LayoutContent>
        </div>
      </LayoutContentWrapper>
    )
  }
}

export default connect(
  state => ({
    gocarData: state.Gocar,
    dataProfile: state.Auth.profile,
    notifications: state.Notifications,

    terminatePolicyLoading: state.Loading.TERMINATE_POLICY,
    terminatePolicyError: state.Error.TERMINATE_POLICY,
    terminatePolicyStatus: state.Gocar.statusTerminatePolicy,

    checkMissingPaymentLoading: state.Loading.CHECK_MISSING_PAYMENT,
    checkMissingPaymentError: state.Error.CHECK_MISSING_PAYMENT,
    missingPayments: state.Gocar.missingPayment,

    addPaymentLoading: state.Loading.ADD_PAYMENT,
    addPaymentError: state.Error.ADD_PAYMENT,
    addPaymentStatus: state.Gocar.addPaymentStatus
  }),
  {
    updatePolicyNumber,
    getGocarDetails,
    getGocarPaymentDetails,
    cancelPolicy,
    resetReduxState,
    terminatePolicy,
    resetNotificationsRedux,
    getNotificationList,
    postRetriggerNotification,
    checkMissingPayment,
    addPayment,
    resetErrorRedux,
    resetLoadingRedux
  }
)(GocarDetail)
